\draw (O) circle (3.4);
\draw (O) -- (A);
\draw (O) -- (B);
\draw[very thick] (B) arc[start angle=60,end angle=300,radius=3.4];
\pic[draw,"interior",angle radius=0.9cm,angle eccentricity=2.1] {angle=B--O--A};
\pic[draw,"exterior",angle radius=2.6cm,angle eccentricity=0.62] {angle=A--O--B};
\node at (-1.9,1.2) {sector};
\fill (O) circle (1.6pt);
\node[left] at (O) {$O$};
\end{tikzpicture}
[/tikz]

foundation.question_text:
[tikz]
\begin{tikzpicture}[scale=0.9]
\coordinate (O) at (0,0);
\coordinate (A) at (0:2.4);
\coordinate (B) at (120:2.4);
\fill[blue!25] (O) -- (120:2.4) arc[start angle=120,end angle=360,radius=2.4] -- cycle;
\draw (O) -- (A);
\draw (O) -- (B);
\draw (120:2.4) arc[start angle=120,end angle=360,radius=2.4];
\pic[draw,"$120^{\circ}$",angle radius=0.7cm,angle eccentricity=2.1] {angle=A--O--B};
\fill (O) circle (1.6pt);
\end{tikzpicture}
[/tikz]
The marked angle is the **exterior** angle of the shaded sector.
Find the interior angle of the sector.

foundation.solution_text:
[tikz]
\begin{tikzpicture}[scale=0.9]
\coordinate (O) at (0,0);
\coordinate (A) at (0:2.4);
\coordinate (B) at (120:2.4);
\fill[blue!25] (O) -- (120:2.4) arc[start angle=120,end angle=360,radius=2.4] -- cycle;
\draw (O) -- (A);
\draw (O) -- (B);
\draw (120:2.4) arc[start angle=120,end angle=360,radius=2.4];
\pic[draw,"$120^{\circ}$",angle radius=0.7cm,angle eccentricity=2.1] {angle=A--O--B};
\draw (120:1.25) arc[start angle=120,end angle=360,radius=1.25];
\node at (240:1.75) {$240^{\circ}$};
\fill (O) circle (1.6pt);
\end{tikzpicture}
[/tikz]
$\theta = 360^{\circ} - 120^{\circ}$
$= 240^{\circ}$

